// import React, { useState, useEffect } from "react";
import { useNavigate } from 'react-router-dom';
import { useAuthorize } from "../context/hook/useAuthorization";
import '../styles/myaccount.css'
import 'animate.css';
import NavMenu from "./SharedComponents/navMenu";
import { Input, Table } from 'antd';
import { SearchOutlined } from '@ant-design/icons';

const WorkspaceRecord = (props) => {
    const { userAccount } = useAuthorize();
    const [workspaces, setWorkspaces] = useState([]);
    const [loading, setLoading] = useState(false);

    // Function to fetch available workspaces from the server
    useEffect(() => {
        const fetchWorkspaces = async () => {
            setLoading(true);
            try {
                const response = await fetch('/api/workspaces/available', {
                    headers: {
                        'Authorization': `Bearer ${userAccount.userToken}`
                    }
                });
                const data = await response.json();
                if (response.ok) {
                    setWorkspaces(data);
                } else {
                    throw new Error(data.error || "Failed to fetch workspaces");
                }
            } catch (error) {
                console.error("Fetching error:", error);
            } finally {
                setLoading(false);
            }
        };

        if (userAccount) {
            fetchWorkspaces();
        }
    }, [userAccount]);

    const columns = [
        {
            title: 'Name',
            dataIndex: 'name',
            key: 'name',
            filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters }) => (
                <Input
                    autoFocus
                    placeholder="Type name here"
                    value={selectedKeys[0]}
                    onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
                    onPressEnter={confirm}
                    onBlur={clearFilters}
                    style={{ marginBottom: 8, display: 'block' }}
                />
            ),
            filterIcon: filtered => <SearchOutlined style={{ color: filtered ? '#1890ff' : undefined }} />,
            onFilter: (value, record) => record.name.toLowerCase().includes(value.toLowerCase()),
        },
        {
            title: 'Location',
            dataIndex: 'location',
            key: 'location',
            onFilter: (value, record) => record.location.toLowerCase().includes(value.toLowerCase()),
            filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters }) => (
                <Input
                    autoFocus
                    placeholder="Type location here"
                    value={selectedKeys[0]}
                    onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
                    onPressEnter={confirm}
                    onBlur={clearFilters}
                    style={{ marginBottom: 8, display: 'block' }}
                />
            ),
            filterIcon: filtered => <SearchOutlined style={{ color: filtered ? '#1890ff' : undefined }} />,
        },
        {
            title: 'Status',
            dataIndex: 'status',
            key: 'status',
            filters: [
                { text: 'Available', value: 'available' },
                { text: 'Unavailable', value: 'unavailable' }
            ],
            onFilter: (value, record) => record.status === value,
        }
    ];

    return (
        <div className="recordpage">
            <NavMenu isAdmin={true} breadcrum="Workspace Overview" pagePath="/workspace-overview" />
            <div className="workspace-overview animate__animated animate__fadeInUp">
                <Table columns={columns} dataSource={workspaces} loading={loading} rowKey="_id" />
            </div>
        </div>
    );
};

export default WorkspaceRecord;
